    text-align: center;
  }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .stats-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
}

