.mobile-nav a:hover { color: var(--accent); }

.mobile-nav .btn {
  margin-top: 1rem;
  width: 100%;
  text-align: center;
}

/* ─── Hero ─── */
.hero {
  padding: 8rem 0 5rem;
  position: relative;
  overflow: hidden;
}

.hero-home {
  padding: 9rem 0 6rem;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
