}

.hero-page h1 {
  margin-bottom: 1rem;
}

.hero-page p {
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
}

/* ─── Features Section ─── */
.features-section {
  padding: 6rem 0;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
