  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--accent);
  background: var(--accent-light);
}

.feature-card h3 {
  margin-bottom: 0.75rem;
}

.feature-card p {
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ─── How It Works ─── */
.how-it-works {
  padding: 6rem 0;
  background: var(--off-white);
}

.steps-grid {
  display: grid;
