.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--navy);
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step-card h3 { margin-bottom: 0.75rem; }
.step-card p { font-size: 0.9375rem; }

/* ─── Stats ─── */
.stats-section {
  padding: 5rem 0;
  background: var(--navy);
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
}

/* ─── Testimonials ─── */
.testimonials-section {
  padding: 6rem 0;
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 500ms ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 3rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  line-height: 1.8;
  color: var(--gray-700);
  margin-bottom: 2rem;
  font-style: italic;
  position: relative;
}

.testimonial-quote::before {
  content: '\201C';
  font-family: var(--font-heading);
  font-size: 4rem;
  color: var(--accent);
  opacity: 0.3;
  position: absolute;
  top: -1.5rem;
  left: 50%;
  transform: translateX(-50%);
}

.testimonial-author {
  font-family: var(--font-heading);
  font-weight: 600;
  color: var(--navy);
  font-size: 1rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.25rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  color: var(--navy);
}

.carousel-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--accent);
  transform: scale(1.2);
}

/* ─── Pricing Teaser ─── */
.pricing-teaser {
  padding: 6rem 0;
  background: var(--off-white);
}

.pricing-teaser-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.pricing-teaser-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: all var(--transition);
}

.pricing-teaser-card:hover {
  box-shadow: var(--shadow-md);
}

.pricing-teaser-card.featured {
  border-color: var(--accent);
  position: relative;
}

.pricing-teaser-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-teaser-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-teaser-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 0.25rem;
}

.pricing-teaser-price span {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-teaser-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 1.5rem;
}

/* ─── CTA Section ─── */
.cta-section {
  padding: 6rem 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  color: var(--white);
  text-align: center;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-section p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  max-width: 560px;
  margin: 0 auto 2rem;
}

/* ─── Footer ─── */
.site-footer {
  background: var(--gray-900);
  color: rgba(255,255,255,0.7);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 1rem;
}

.footer-brand .logo-icon {
  background: var(--accent);
}

.footer-brand p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.7;
  max-width: 280px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  padding: 0.3rem 0;
  color: rgba(255,255,255,0.5);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ─── Pricing Page ─── */
.pricing-section {
  padding: 4rem 0 6rem;
}

.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.billing-toggle span {
  font-family: var(--font-heading);
  font-weight: 500;
  color: var(--gray-500);
  font-size: 0.9375rem;
}

.billing-toggle span.active {
  color: var(--navy);
  font-weight: 600;
}

.toggle-switch {
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 999px;
  position: relative;
  cursor: pointer;
  transition: background var(--transition);
}

.toggle-switch.active {
  background: var(--accent);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(24px);
}

.save-badge {
  background: var(--success);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 2.5rem 2rem;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--accent);
  box-shadow: var(--shadow-lg);
  position: relative;
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-card-header {
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-tier-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-amount {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
}

.pricing-amount .period {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.5rem;
}

.pricing-features {
  flex: 1;
  margin-bottom: 2rem;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--gray-700);
}

.pricing-features li svg {
  flex-shrink: 0;
  margin-top: 3px;
}

.check-icon {
  color: var(--success);
}

.dash-icon {
  color: var(--gray-400);
}

.pricing-card .btn {
  width: 100%;
}

/* ─── FAQ ─── */
.faq-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  background: none;
  border: none;
  cursor: pointer;
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
}

.faq-question:hover { color: var(--accent); }

.faq-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  transition: transform 300ms ease;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 1.25rem;
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* ─── About Page ─── */
.mission-section {
  padding: 6rem 0;
}

.mission-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

.team-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.team-card {
  text-align: center;
  padding: 2rem;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}

.team-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.team-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  margin: 0 auto 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
}

.team-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.25rem;
}

.team-card p {
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* ─── Contact Page ─── */
.contact-section {
  padding: 4rem 0 6rem;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
}

.contact-form {
  background: var(--white);
  padding: 2.5rem;
  border-radius: var(--radius-xl);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-sm);
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-group label .required {
  color: var(--red);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  color: var(--gray-800);
  background: var(--white);
  transition: all var(--transition);
  outline: none;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}

.form-group input.error,
.form-group textarea.error {
  border-color: var(--red);
}

.form-error {
  font-size: 0.8125rem;
  color: var(--red);
  margin-top: 0.375rem;
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem 2rem;
}

.form-success.show {
  display: block;
}

.form-success-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(16, 185, 129, 0.1);
  color: var(--success);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.form-success h3 {
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-success p {
  font-size: 0.9375rem;
}

.office-cards {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.office-card {
  padding: 1.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  background: var(--white);
}

.office-card h3 {
  font-size: 1rem;
  margin-bottom: 0.375rem;
}

.office-card p {
  font-size: 0.875rem;
}

.contact-info-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
}

.contact-info-item svg {
  flex-shrink: 0;
  color: var(--accent);
}

/* ─── Feature Detail Sections ─── */
.feature-detail {
  padding: 6rem 0;
}

.feature-detail:nth-child(even) {
  background: var(--off-white);
}

.feature-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.feature-detail:nth-child(odd) .feature-detail-grid {
  direction: rtl;
}

.feature-detail:nth-child(odd) .feature-detail-grid > * {
  direction: ltr;
}

.feature-detail-content h2 {
  margin-bottom: 1rem;
}

.feature-detail-content p {
  font-size: 1.0625rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

.feature-detail-visual {
  background: var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feature-detail-visual .visual-placeholder {
  text-align: center;
  color: var(--gray-400);
}

.feature-detail-visual .visual-placeholder svg {
  margin-bottom: 0.5rem;
}

/* Integrations */
.integrations-section {
  padding: 6rem 0;
}

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.integration-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  text-align: center;
  transition: all var(--transition);
}

.integration-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--accent);
}

.integration-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  color: var(--accent);
}

.integration-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.integration-card p {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ─── Animations ─── */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease, transform 600ms ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }

  .hero-visual { order: -1; }

  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-cards { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }

  .feature-detail-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .feature-detail:nth-child(odd) .feature-detail-grid {
    direction: ltr;
  }
}

@media (max-width: 768px) {
  .nav-links, .header-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }

  .hero-home { padding: 7rem 0 4rem; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .pricing-cards { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: none; }
  .pricing-teaser-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .team-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr 1fr; }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 0.75rem;
    text-align: center;
  }

  .hero-buttons {
    flex-direction: column;
  }

  .hero-buttons .btn {
    width: 100%;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .stats-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
}
