/* ShiftWise — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --navy: #0B1D3A;
  --navy-light: #122A52;
  --navy-mid: #1A3A6E;
  --primary: #0051C3;
  --primary-hover: #003D94;
  --accent: #F26B3A;
  --accent-hover: #D9551F;
  --accent-light: rgba(242, 107, 58, 0.1);
  --red: #DE5052;
  --white: #FFFFFF;
  --off-white: #F7F8FA;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --success: #10B981;
  --font-heading: 'Space Grotesk', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --shadow-sm: 0 1px 2px rgba(11,29,58,0.05);
  --shadow-md: 0 4px 12px rgba(11,29,58,0.08);
  --shadow-lg: 0 12px 32px rgba(11,29,58,0.12);
  --shadow-xl: 0 20px 48px rgba(11,29,58,0.16);
  --radius-sm: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --transition: 200ms ease;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ─── Typography ─── */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--navy);
  line-height: 1.2;
  font-weight: 700;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }

p { color: var(--gray-600); }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--gray-500);
  max-width: 640px;
  margin: 0 auto 2.5rem;
}

.text-center { text-align: center; }

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  padding: 0.875rem 1.75rem;
  border-radius: var(--radius-md);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
  border-color: var(--accent);
}
.btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--navy);
  border-color: var(--gray-300);
}
.btn-secondary:hover {
  border-color: var(--navy);
  background: var(--gray-50);
}

.btn-white {
  background: var(--white);
  color: var(--navy);
  border-color: var(--white);
}
.btn-white:hover {
  background: var(--off-white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline-white {
  background: transparent;
  color: var(--white);
  border-color: rgba(255,255,255,0.4);
}
.btn-outline-white:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.7);
}

.btn-sm {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.125rem;
}

/* ─── Header ─── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: all var(--transition);
}

.site-header.scrolled {
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--navy);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  font-size: 1.25rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--gray-600);
  transition: color var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--navy);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
}

.header-cta {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  z-index: 1001;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--navy);
  border-radius: 2px;
  transition: all 300ms ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 999;
  padding: 6rem 2rem 2rem;
  flex-direction: column;
  gap: 0.5rem;
  opacity: 0;
  transform: translateX(100%);
  transition: all 350ms ease;
}

.mobile-nav.open {
  opacity: 1;
  transform: translateX(0);
}

.mobile-nav a {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--navy);
  padding: 1rem 0;
  border-bottom: 1px solid var(--gray-100);
  transition: color var(--transition);
}

.mobile-nav a:hover { color: var(--accent); }

.mobile-nav .btn {
  margin-top: 1rem;
  width: 100%;
  text-align: center;
}

/* ─── Hero ─── */
.hero {
  padding: 8rem 0 5rem;
  position: relative;
  overflow: hidden;
}

.hero-home {
  padding: 9rem 0 6rem;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  color: var(--white);
}

.hero-home .hero-content {
  max-width: 720px;
}

.hero-home h1 {
  color: var(--white);
  margin-bottom: 1.5rem;
}

.hero-home p {
  color: rgba(255,255,255,0.8);
  font-size: 1.25rem;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.hero-visual {
  position: relative;
}

.hero-mockup {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: var(--radius-lg);
  padding: 2rem;
  backdrop-filter: blur(8px);
}

.hero-mockup-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 1.5rem;
}

.hero-mockup-bar span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
}

.hero-mockup-bar span:first-child { background: var(--red); }
.hero-mockup-bar span:nth-child(2) { background: #FBBF24; }
.hero-mockup-bar span:nth-child(3) { background: var(--success); }

.hero-mockup-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
}

.hero-mockup-cell {
  height: 32px;
  border-radius: 4px;
  background: rgba(255,255,255,0.06);
}

.hero-mockup-cell.filled {
  background: var(--accent);
  opacity: 0.7;
}

.hero-mockup-cell.filled-alt {
  background: var(--primary);
  opacity: 0.6;
}

.hero-page {
  padding: 8rem 0 4rem;
  background: var(--off-white);
  text-align: center;
}

.hero-page h1 {
  margin-bottom: 1rem;
}

.hero-page p {
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
}

/* ─── Features Section ─── */
.features-section {
  padding: 6rem 0;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.feature-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.feature-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--accent);
  background: var(--accent-light);
}

.feature-card h3 {
  margin-bottom: 0.75rem;
}

.feature-card p {
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ─── How It Works ─── */
.how-it-works {
  padding: 6rem 0;
  background: var(--off-white);
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--navy);
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step-card h3 { margin-bottom: 0.75rem; }
.step-card p { font-size: 0.9375rem; }

/* ─── Stats ─── */
.stats-section {
  padding: 5rem 0;
  background: var(--navy);
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
}

/* ─── Testimonials ─── */
.testimonials-section {
  padding: 6rem 0;
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 500ms ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 3rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  line-height: 1.8;
  color: var(--gray-700);
  margin-bottom: 2rem;
  font-style: italic;
  position: relative;
}

.testimonial-quote::before {
  content: '\201C';
  font-family: var(--font-heading);
  font-size: 4rem;
  color: var(--accent);
  opacity: 0.3;
  position: absolute;
  top: -1.5rem;
  left: 50%;
  transform: translateX(-50%);
}

.testimonial-author {
  font-family: var(--font-heading);
  font-weight: 600;
  color: var(--navy);
  font-size: 1rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.25rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  color: var(--navy);
}

.carousel-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--accent);
  transform: scale(1.2);
}

/* ─── Pricing Teaser ─── */
.pricing-teaser {
  padding: 6rem 0;
  background: var(--off-white);
}

.pricing-teaser-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.pricing-teaser-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: all var(--transition);
}

.pricing-teaser-card:hover {
  box-shadow: var(--shadow-md);
}

.pricing-teaser-card.featured {
  border-color: var(--accent);
  position: relative;
}

.pricing-teaser-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-teaser-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-teaser-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 0.25rem;
}

.pricing-teaser-price span {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-teaser-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 1.5rem;
}

/* ─── CTA Section ─── */
.cta-section {
  padding: 6rem 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  color: var(--white);
  text-align: center;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-section p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  max-width: 560px;
  margin: 0 auto 2rem;
}

/* ─── Footer ─── */
.site-footer {
  background: var(--gray-900);
  color: rgba(255,255,255,0.7);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 1rem;
}

.footer-brand .logo-icon {
  background: var(--accent);
}

.footer-brand p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.7;
  max-width: 280px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  padding: 0.3rem 0;
  color: rgba(255,255,255,0.5);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ─── Pricing Page ─── */
.pricing-section {
  padding: 4rem 0 6rem;
}

.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.billing-toggle span {
  font-family: var(--font-heading);
  font-weight: 500;
  color: var(--gray-500);
  font-size: 0.9375rem;
}

.billing-toggle span.active {
  color: var(--navy);
  font-weight: 600;
}

.toggle-switch {
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 999px;
  position: relative;
  cursor: pointer;
  transition: background var(--transition);
}

.toggle-switch.active {
  background: var(--accent);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(24px);
}

.save-badge {
  background: var(--success);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 2.5rem 2rem;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--accent);
  box-shadow: var(--shadow-lg);
  position: relative;
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-card-header {
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-tier-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-amount {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
}

.pricing-amount .period {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.5rem;
}

.pricing-features {
  flex: 1;
  margin-bottom: 2rem;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--gray-700);
}

.pricing-features li svg {
  flex-shrink: 0;
  margin-top: 3px;
}

.check-icon {
  color: var(--success);
}

.dash-icon {
  color: var(--gray-400);
}

.pricing-card .btn {
  width: 100%;
}

/* ─── FAQ ─── */
.faq-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  background: none;
  border: none;
  cursor: pointer;
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
}

.faq-question:hover { color: var(--accent); }

.faq-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  transition: transform 300ms ease;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 1.25rem;
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* ─── About Page ─── */
.mission-section {
  padding: 6rem 0;
}

.mission-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

.team-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.team-card {
  text-align: center;
  padding: 2rem;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}

.team-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.team-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  margin: 0 auto 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
}

.team-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.25rem;
}

.team-card p {
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* ─── Contact Page ─── */
.contact-section {
  padding: 4rem 0 6rem;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
}

.contact-form {
  background: var(--white);
  padding: 2.5rem;
  border-radius: var(--radius-xl);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-sm);
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-group label .required {
  color: var(--red);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  color: var(--gray-800);
  background: var(--white);
  transition: all var(--transition);
  outline: none;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}

.form-group input.error,
.form-group textarea.error {
  border-color: var(--red);
}

.form-error {
  font-size: 0.8125rem;
  color: var(--red);
  margin-top: 0.375rem;
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem 2rem;
}

.form-success.show {
  display: block;
}

.form-success-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(16, 185, 129, 0.1);
  color: var(--success);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.form-success h3 {
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-success p {
  font-size: 0.9375rem;
}

.office-cards {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.office-card {
  padding: 1.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  background: var(--white);
}

.office-card h3 {
  font-size: 1rem;
  margin-bottom: 0.375rem;
}

.office-card p {
  font-size: 0.875rem;
}

.contact-info-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
}

.contact-info-item svg {
  flex-shrink: 0;
  color: var(--accent);
}

/* ─── Feature Detail Sections ─── */
.feature-detail {
  padding: 6rem 0;
}

.feature-detail:nth-child(even) {
  background: var(--off-white);
}

.feature-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.feature-detail:nth-child(odd) .feature-detail-grid {
  direction: rtl;
}

.feature-detail:nth-child(odd) .feature-detail-grid > * {
  direction: ltr;
}

.feature-detail-content h2 {
  margin-bottom: 1rem;
}

.feature-detail-content p {
  font-size: 1.0625rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

.feature-detail-visual {
  background: var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feature-detail-visual .visual-placeholder {
  text-align: center;
  color: var(--gray-400);
}

.feature-detail-visual .visual-placeholder svg {
  margin-bottom: 0.5rem;
}

/* Integrations */
.integrations-section {
  padding: 6rem 0;
}

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.integration-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  text-align: center;
  transition: all var(--transition);
}

.integration-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--accent);
}

.integration-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  color: var(--accent);
}

.integration-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.integration-card p {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ─── Animations ─── */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease, transform 600ms ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }

  .hero-visual { order: -1; }

  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-cards { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }

  .feature-detail-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .feature-detail:nth-child(odd) .feature-detail-grid {
    direction: ltr;
  }
}

@media (max-width: 768px) {
  .nav-links, .header-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }

  .hero-home { padding: 7rem 0 4rem; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .pricing-cards { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: none; }
  .pricing-teaser-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .team-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr 1fr; }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 0.75rem;
    text-align: center;
  }

  .hero-buttons {
    flex-direction: column;
  }

  .hero-buttons .btn {
    width: 100%;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .stats-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
}

/* ShiftWise — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --navy: #0B1D3A;
  --navy-light: #122A52;
  --navy-mid: #1A3A6E;
  --primary: #0051C3;
  --primary-hover: #003D94;
  --accent: #F26B3A;
  --accent-hover: #D9551F;
  --accent-light: rgba(242, 107, 58, 0.1);
  --red: #DE5052;
  --white: #FFFFFF;
  --off-white: #F7F8FA;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --success: #10B981;
  --font-heading: 'Space Grotesk', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --shadow-sm: 0 1px 2px rgba(11,29,58,0.05);
  --shadow-md: 0 4px 12px rgba(11,29,58,0.08);
  --shadow-lg: 0 12px 32px rgba(11,29,58,0.12);
  --shadow-xl: 0 20px 48px rgba(11,29,58,0.16);
  --radius-sm: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --transition: 200ms ease;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ─── Typography ─── */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--navy);
  line-height: 1.2;
  font-weight: 700;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }

p { color: var(--gray-600); }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--gray-500);
  max-width: 640px;
  margin: 0 auto 2.5rem;
}

.text-center { text-align: center; }

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  padding: 0.875rem 1.75rem;
  border-radius: var(--radius-md);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
  border-color: var(--accent);
}
.btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--navy);
  border-color: var(--gray-300);
}
.btn-secondary:hover {
  border-color: var(--navy);
  background: var(--gray-50);
}

.btn-white {
  background: var(--white);
  color: var(--navy);
  border-color: var(--white);
}
.btn-white:hover {
  background: var(--off-white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline-white {
  background: transparent;
  color: var(--white);
  border-color: rgba(255,255,255,0.4);
}
.btn-outline-white:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.7);
}

.btn-sm {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.125rem;
}

/* ─── Header ─── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: all var(--transition);
}

.site-header.scrolled {
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--navy);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  font-size: 1.25rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--gray-600);
  transition: color var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--navy);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
}

.header-cta {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  z-index: 1001;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--navy);
  border-radius: 2px;
  transition: all 300ms ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 999;
  padding: 6rem 2rem 2rem;
  flex-direction: column;
  gap: 0.5rem;
  opacity: 0;
  transform: translateX(100%);
  transition: all 350ms ease;
}

.mobile-nav.open {
  opacity: 1;
  transform: translateX(0);
}

.mobile-nav a {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--navy);
  padding: 1rem 0;
  border-bottom: 1px solid var(--gray-100);
  transition: color var(--transition);
}

.mobile-nav a:hover { color: var(--accent); }

.mobile-nav .btn {
  margin-top: 1rem;
  width: 100%;
  text-align: center;
}

/* ─── Hero ─── */
.hero {
  padding: 8rem 0 5rem;
  position: relative;
  overflow: hidden;
}

.hero-home {
  padding: 9rem 0 6rem;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  color: var(--white);
}

.hero-home .hero-content {
  max-width: 720px;
}

.hero-home h1 {
  color: var(--white);
  margin-bottom: 1.5rem;
}

.hero-home p {
  color: rgba(255,255,255,0.8);
  font-size: 1.25rem;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.hero-visual {
  position: relative;
}

.hero-mockup {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: var(--radius-lg);
  padding: 2rem;
  backdrop-filter: blur(8px);
}

.hero-mockup-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 1.5rem;
}

.hero-mockup-bar span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
}

.hero-mockup-bar span:first-child { background: var(--red); }
.hero-mockup-bar span:nth-child(2) { background: #FBBF24; }
.hero-mockup-bar span:nth-child(3) { background: var(--success); }

.hero-mockup-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
}

.hero-mockup-cell {
  height: 32px;
  border-radius: 4px;
  background: rgba(255,255,255,0.06);
}

.hero-mockup-cell.filled {
  background: var(--accent);
  opacity: 0.7;
}

.hero-mockup-cell.filled-alt {
  background: var(--primary);
  opacity: 0.6;
}

.hero-page {
  padding: 8rem 0 4rem;
  background: var(--off-white);
  text-align: center;
}

.hero-page h1 {
  margin-bottom: 1rem;
}

.hero-page p {
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
}

/* ─── Features Section ─── */
.features-section {
  padding: 6rem 0;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.feature-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.feature-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--accent);
  background: var(--accent-light);
}

.feature-card h3 {
  margin-bottom: 0.75rem;
}

.feature-card p {
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ─── How It Works ─── */
.how-it-works {
  padding: 6rem 0;
  background: var(--off-white);
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--navy);
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step-card h3 { margin-bottom: 0.75rem; }
.step-card p { font-size: 0.9375rem; }

/* ─── Stats ─── */
.stats-section {
  padding: 5rem 0;
  background: var(--navy);
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
}

/* ─── Testimonials ─── */
.testimonials-section {
  padding: 6rem 0;
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 500ms ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 3rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  line-height: 1.8;
  color: var(--gray-700);
  margin-bottom: 2rem;
  font-style: italic;
  position: relative;
}

.testimonial-quote::before {
  content: '\201C';
  font-family: var(--font-heading);
  font-size: 4rem;
  color: var(--accent);
  opacity: 0.3;
  position: absolute;
  top: -1.5rem;
  left: 50%;
  transform: translateX(-50%);
}

.testimonial-author {
  font-family: var(--font-heading);
  font-weight: 600;
  color: var(--navy);
  font-size: 1rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.25rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  color: var(--navy);
}

.carousel-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--accent);
  transform: scale(1.2);
}

/* ─── Pricing Teaser ─── */
.pricing-teaser {
  padding: 6rem 0;
  background: var(--off-white);
}

.pricing-teaser-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.pricing-teaser-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: all var(--transition);
}

.pricing-teaser-card:hover {
  box-shadow: var(--shadow-md);
}

.pricing-teaser-card.featured {
  border-color: var(--accent);
  position: relative;
}

.pricing-teaser-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-teaser-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-teaser-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 0.25rem;
}

.pricing-teaser-price span {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-teaser-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 1.5rem;
}

/* ─── CTA Section ─── */
.cta-section {
  padding: 6rem 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  color: var(--white);
  text-align: center;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-section p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  max-width: 560px;
  margin: 0 auto 2rem;
}

/* ─── Footer ─── */
.site-footer {
  background: var(--gray-900);
  color: rgba(255,255,255,0.7);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 1rem;
}

.footer-brand .logo-icon {
  background: var(--accent);
}

.footer-brand p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.7;
  max-width: 280px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  padding: 0.3rem 0;
  color: rgba(255,255,255,0.5);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ─── Pricing Page ─── */
.pricing-section {
  padding: 4rem 0 6rem;
}

.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.billing-toggle span {
  font-family: var(--font-heading);
  font-weight: 500;
  color: var(--gray-500);
  font-size: 0.9375rem;
}

.billing-toggle span.active {
  color: var(--navy);
  font-weight: 600;
}

.toggle-switch {
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 999px;
  position: relative;
  cursor: pointer;
  transition: background var(--transition);
}

.toggle-switch.active {
  background: var(--accent);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(24px);
}

.save-badge {
  background: var(--success);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 2.5rem 2rem;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--accent);
  box-shadow: var(--shadow-lg);
  position: relative;
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-card-header {
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-tier-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-amount {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
}

.pricing-amount .period {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.5rem;
}

.pricing-features {
  flex: 1;
  margin-bottom: 2rem;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--gray-700);
}

.pricing-features li svg {
  flex-shrink: 0;
  margin-top: 3px;
}

.check-icon {
  color: var(--success);
}

.dash-icon {
  color: var(--gray-400);
}

.pricing-card .btn {
  width: 100%;
}

/* ─── FAQ ─── */
.faq-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  background: none;
  border: none;
  cursor: pointer;
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
}

.faq-question:hover { color: var(--accent); }

.faq-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  transition: transform 300ms ease;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 1.25rem;
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* ─── About Page ─── */
.mission-section {
  padding: 6rem 0;
}

.mission-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

.team-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.team-card {
  text-align: center;
  padding: 2rem;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}

.team-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.team-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  margin: 0 auto 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
}

.team-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.25rem;
}

.team-card p {
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* ─── Contact Page ─── */
.contact-section {
  padding: 4rem 0 6rem;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
}

.contact-form {
  background: var(--white);
  padding: 2.5rem;
  border-radius: var(--radius-xl);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-sm);
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-group label .required {
  color: var(--red);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  color: var(--gray-800);
  background: var(--white);
  transition: all var(--transition);
  outline: none;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}

.form-group input.error,
.form-group textarea.error {
  border-color: var(--red);
}

.form-error {
  font-size: 0.8125rem;
  color: var(--red);
  margin-top: 0.375rem;
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem 2rem;
}

.form-success.show {
  display: block;
}

.form-success-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(16, 185, 129, 0.1);
  color: var(--success);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.form-success h3 {
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-success p {
  font-size: 0.9375rem;
}

.office-cards {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.office-card {
  padding: 1.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  background: var(--white);
}

.office-card h3 {
  font-size: 1rem;
  margin-bottom: 0.375rem;
}

.office-card p {
  font-size: 0.875rem;
}

.contact-info-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
}

.contact-info-item svg {
  flex-shrink: 0;
  color: var(--accent);
}

/* ─── Feature Detail Sections ─── */
.feature-detail {
  padding: 6rem 0;
}

.feature-detail:nth-child(even) {
  background: var(--off-white);
}

.feature-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.feature-detail:nth-child(odd) .feature-detail-grid {
  direction: rtl;
}

.feature-detail:nth-child(odd) .feature-detail-grid > * {
  direction: ltr;
}

.feature-detail-content h2 {
  margin-bottom: 1rem;
}

.feature-detail-content p {
  font-size: 1.0625rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

.feature-detail-visual {
  background: var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feature-detail-visual .visual-placeholder {
  text-align: center;
  color: var(--gray-400);
}

.feature-detail-visual .visual-placeholder svg {
  margin-bottom: 0.5rem;
}

/* Integrations */
.integrations-section {
  padding: 6rem 0;
}

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.integration-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  text-align: center;
  transition: all var(--transition);
}

.integration-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--accent);
}

.integration-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  color: var(--accent);
}

.integration-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.integration-card p {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ─── Animations ─── */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease, transform 600ms ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }

  .hero-visual { order: -1; }

  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-cards { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }

  .feature-detail-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .feature-detail:nth-child(odd) .feature-detail-grid {
    direction: ltr;
  }
}

@media (max-width: 768px) {
  .nav-links, .header-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }

  .hero-home { padding: 7rem 0 4rem; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .pricing-cards { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: none; }
  .pricing-teaser-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .team-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr 1fr; }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 0.75rem;
    text-align: center;
  }

  .hero-buttons {
    flex-direction: column;
  }

  .hero-buttons .btn {
    width: 100%;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .stats-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
}

raw_arguments.content:
/* ShiftWise — Global Styles */
@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --navy: #0B1D3A;
  --navy-light: #122A52;
  --navy-mid: #1A3A6E;
  --primary: #0051C3;
  --primary-hover: #003D94;
  --accent: #F26B3A;
  --accent-hover: #D9551F;
  --accent-light: rgba(242, 107, 58, 0.1);
  --red: #DE5052;
  --white: #FFFFFF;
  --off-white: #F7F8FA;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --gray-800: #1F2937;
  --gray-900: #111827;
  --success: #10B981;
  --font-heading: 'Space Grotesk', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --shadow-sm: 0 1px 2px rgba(11,29,58,0.05);
  --shadow-md: 0 4px 12px rgba(11,29,58,0.08);
  --shadow-lg: 0 12px 32px rgba(11,29,58,0.12);
  --shadow-xl: 0 20px 48px rgba(11,29,58,0.16);
  --radius-sm: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.5rem;
  --transition: 200ms ease;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }

.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ─── Typography ─── */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--navy);
  line-height: 1.2;
  font-weight: 700;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }

p { color: var(--gray-600); }

.section-label {
  display: inline-block;
  font-family: var(--font-heading);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 0.75rem;
}

.section-title {
  margin-bottom: 1rem;
}

.section-subtitle {
  font-size: 1.125rem;
  color: var(--gray-500);
  max-width: 640px;
  margin: 0 auto 2.5rem;
}

.text-center { text-align: center; }

/* ─── Buttons ─── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 1rem;
  padding: 0.875rem 1.75rem;
  border-radius: var(--radius-md);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
  border-color: var(--accent);
}
.btn-primary:hover {
  background: var(--accent-hover);
  border-color: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--navy);
  border-color: var(--gray-300);
}
.btn-secondary:hover {
  border-color: var(--navy);
  background: var(--gray-50);
}

.btn-white {
  background: var(--white);
  color: var(--navy);
  border-color: var(--white);
}
.btn-white:hover {
  background: var(--off-white);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-outline-white {
  background: transparent;
  color: var(--white);
  border-color: rgba(255,255,255,0.4);
}
.btn-outline-white:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.7);
}

.btn-sm {
  padding: 0.625rem 1.25rem;
  font-size: 0.875rem;
}

.btn-lg {
  padding: 1rem 2.25rem;
  font-size: 1.125rem;
}

/* ─── Header ─── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: all var(--transition);
}

.site-header.scrolled {
  box-shadow: var(--shadow-sm);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.5rem;
  color: var(--navy);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  font-size: 1.25rem;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-links a {
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 0.9375rem;
  color: var(--gray-600);
  transition: color var(--transition);
  position: relative;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--navy);
}

.nav-links a.active::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--accent);
  border-radius: 1px;
}

.header-cta {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0.5rem;
  z-index: 1001;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--navy);
  border-radius: 2px;
  transition: all 300ms ease;
}

.hamburger.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.hamburger.active span:nth-child(2) {
  opacity: 0;
}

.hamburger.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 999;
  padding: 6rem 2rem 2rem;
  flex-direction: column;
  gap: 0.5rem;
  opacity: 0;
  transform: translateX(100%);
  transition: all 350ms ease;
}

.mobile-nav.open {
  opacity: 1;
  transform: translateX(0);
}

.mobile-nav a {
  display: block;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--navy);
  padding: 1rem 0;
  border-bottom: 1px solid var(--gray-100);
  transition: color var(--transition);
}

.mobile-nav a:hover { color: var(--accent); }

.mobile-nav .btn {
  margin-top: 1rem;
  width: 100%;
  text-align: center;
}

/* ─── Hero ─── */
.hero {
  padding: 8rem 0 5rem;
  position: relative;
  overflow: hidden;
}

.hero-home {
  padding: 9rem 0 6rem;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  color: var(--white);
}

.hero-home .hero-content {
  max-width: 720px;
}

.hero-home h1 {
  color: var(--white);
  margin-bottom: 1.5rem;
}

.hero-home p {
  color: rgba(255,255,255,0.8);
  font-size: 1.25rem;
  margin-bottom: 2.5rem;
  line-height: 1.7;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.hero-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.hero-visual {
  position: relative;
}

.hero-mockup {
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: var(--radius-lg);
  padding: 2rem;
  backdrop-filter: blur(8px);
}

.hero-mockup-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 1.5rem;
}

.hero-mockup-bar span {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.3);
}

.hero-mockup-bar span:first-child { background: var(--red); }
.hero-mockup-bar span:nth-child(2) { background: #FBBF24; }
.hero-mockup-bar span:nth-child(3) { background: var(--success); }

.hero-mockup-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
}

.hero-mockup-cell {
  height: 32px;
  border-radius: 4px;
  background: rgba(255,255,255,0.06);
}

.hero-mockup-cell.filled {
  background: var(--accent);
  opacity: 0.7;
}

.hero-mockup-cell.filled-alt {
  background: var(--primary);
  opacity: 0.6;
}

.hero-page {
  padding: 8rem 0 4rem;
  background: var(--off-white);
  text-align: center;
}

.hero-page h1 {
  margin-bottom: 1rem;
}

.hero-page p {
  font-size: 1.125rem;
  max-width: 600px;
  margin: 0 auto;
}

/* ─── Features Section ─── */
.features-section {
  padding: 6rem 0;
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.feature-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.feature-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--accent);
  background: var(--accent-light);
}

.feature-card h3 {
  margin-bottom: 0.75rem;
}

.feature-card p {
  font-size: 0.9375rem;
  line-height: 1.6;
}

/* ─── How It Works ─── */
.how-it-works {
  padding: 6rem 0;
  background: var(--off-white);
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--navy);
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.25rem;
}

.step-card h3 { margin-bottom: 0.75rem; }
.step-card p { font-size: 0.9375rem; }

/* ─── Stats ─── */
.stats-section {
  padding: 5rem 0;
  background: var(--navy);
  color: var(--white);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.stat-item {}

.stat-value {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 0.5rem;
}

.stat-label {
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
}

/* ─── Testimonials ─── */
.testimonials-section {
  padding: 6rem 0;
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 500ms ease;
}

.testimonial-card {
  min-width: 100%;
  padding: 3rem;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.25rem;
  line-height: 1.8;
  color: var(--gray-700);
  margin-bottom: 2rem;
  font-style: italic;
  position: relative;
}

.testimonial-quote::before {
  content: '\201C';
  font-family: var(--font-heading);
  font-size: 4rem;
  color: var(--accent);
  opacity: 0.3;
  position: absolute;
  top: -1.5rem;
  left: 50%;
  transform: translateX(-50%);
}

.testimonial-author {
  font-family: var(--font-heading);
  font-weight: 600;
  color: var(--navy);
  font-size: 1rem;
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.25rem;
}

.carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--gray-300);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all var(--transition);
  color: var(--navy);
}

.carousel-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-300);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.carousel-dot.active {
  background: var(--accent);
  transform: scale(1.2);
}

/* ─── Pricing Teaser ─── */
.pricing-teaser {
  padding: 6rem 0;
  background: var(--off-white);
}

.pricing-teaser-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.pricing-teaser-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  border: 1px solid var(--gray-200);
  text-align: center;
  transition: all var(--transition);
}

.pricing-teaser-card:hover {
  box-shadow: var(--shadow-md);
}

.pricing-teaser-card.featured {
  border-color: var(--accent);
  position: relative;
}

.pricing-teaser-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-teaser-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-teaser-price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--navy);
  margin-bottom: 0.25rem;
}

.pricing-teaser-price span {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-teaser-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 1.5rem;
}

/* ─── CTA Section ─── */
.cta-section {
  padding: 6rem 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  color: var(--white);
  text-align: center;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 1rem;
}

.cta-section p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  max-width: 560px;
  margin: 0 auto 2rem;
}

/* ─── Footer ─── */
.site-footer {
  background: var(--gray-900);
  color: rgba(255,255,255,0.7);
  padding: 4rem 0 2rem;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 1rem;
}

.footer-brand .logo-icon {
  background: var(--accent);
}

.footer-brand p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.7;
  max-width: 280px;
}

.footer-col h4 {
  font-family: var(--font-heading);
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.footer-col a {
  display: block;
  font-size: 0.875rem;
  padding: 0.3rem 0;
  color: rgba(255,255,255,0.5);
  transition: color var(--transition);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 2rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.4);
}

/* ─── Pricing Page ─── */
.pricing-section {
  padding: 4rem 0 6rem;
}

.billing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 3rem;
}

.billing-toggle span {
  font-family: var(--font-heading);
  font-weight: 500;
  color: var(--gray-500);
  font-size: 0.9375rem;
}

.billing-toggle span.active {
  color: var(--navy);
  font-weight: 600;
}

.toggle-switch {
  width: 52px;
  height: 28px;
  background: var(--gray-300);
  border-radius: 999px;
  position: relative;
  cursor: pointer;
  transition: background var(--transition);
}

.toggle-switch.active {
  background: var(--accent);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(24px);
}

.save-badge {
  background: var(--success);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

.pricing-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 2.5rem 2rem;
  transition: all var(--transition);
  display: flex;
  flex-direction: column;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
}

.pricing-card.featured {
  border-color: var(--accent);
  box-shadow: var(--shadow-lg);
  position: relative;
  transform: scale(1.02);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--accent);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 1rem;
  border-radius: 999px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.pricing-card-header {
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-tier-name {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.pricing-amount {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
}

.pricing-amount .period {
  font-size: 1rem;
  color: var(--gray-500);
  font-weight: 400;
}

.pricing-desc {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-top: 0.5rem;
}

.pricing-features {
  flex: 1;
  margin-bottom: 2rem;
}

.pricing-features li {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 0.5rem 0;
  font-size: 0.9375rem;
  color: var(--gray-700);
}

.pricing-features li svg {
  flex-shrink: 0;
  margin-top: 3px;
}

.check-icon {
  color: var(--success);
}

.dash-icon {
  color: var(--gray-400);
}

.pricing-card .btn {
  width: 100%;
}

/* ─── FAQ ─── */
.faq-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.faq-list {
  max-width: 720px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1.25rem 0;
  background: none;
  border: none;
  cursor: pointer;
  font-family: var(--font-heading);
  font-size: 1.0625rem;
  font-weight: 600;
  color: var(--navy);
  text-align: left;
}

.faq-question:hover { color: var(--accent); }

.faq-icon {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  transition: transform 300ms ease;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease, padding 300ms ease;
}

.faq-item.open .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 1.25rem;
  font-size: 0.9375rem;
  line-height: 1.7;
}

/* ─── About Page ─── */
.mission-section {
  padding: 6rem 0;
}

.mission-content {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

.team-section {
  padding: 6rem 0;
  background: var(--off-white);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.team-card {
  text-align: center;
  padding: 2rem;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  transition: all var(--transition);
}

.team-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.team-avatar {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  margin: 0 auto 1.25rem;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-family: var(--font-heading);
  font-weight: 700;
  font-size: 1.25rem;
}

.team-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.25rem;
}

.team-card p {
  font-size: 0.875rem;
  color: var(--gray-500);
}

/* ─── Contact Page ─── */
.contact-section {
  padding: 4rem 0 6rem;
}

.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
}

.contact-form {
  background: var(--white);
  padding: 2.5rem;
  border-radius: var(--radius-xl);
  border: 1px solid var(--gray-200);
  box-shadow: var(--shadow-sm);
}

.form-group {
  margin-bottom: 1.5rem;
}

.form-group label {
  display: block;
  font-family: var(--font-heading);
  font-weight: 500;
  font-size: 0.875rem;
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-group label .required {
  color: var(--red);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-sm);
  font-family: var(--font-body);
  font-size: 0.9375rem;
  color: var(--gray-800);
  background: var(--white);
  transition: all var(--transition);
  outline: none;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}

.form-group input.error,
.form-group textarea.error {
  border-color: var(--red);
}

.form-error {
  font-size: 0.8125rem;
  color: var(--red);
  margin-top: 0.375rem;
  display: none;
}

.form-group.has-error .form-error {
  display: block;
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-success {
  display: none;
  text-align: center;
  padding: 3rem 2rem;
}

.form-success.show {
  display: block;
}

.form-success-icon {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: rgba(16, 185, 129, 0.1);
  color: var(--success);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem;
}

.form-success h3 {
  color: var(--navy);
  margin-bottom: 0.5rem;
}

.form-success p {
  font-size: 0.9375rem;
}

.office-cards {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.office-card {
  padding: 1.5rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--gray-200);
  background: var(--white);
}

.office-card h3 {
  font-size: 1rem;
  margin-bottom: 0.375rem;
}

.office-card p {
  font-size: 0.875rem;
}

.contact-info-item {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
}

.contact-info-item svg {
  flex-shrink: 0;
  color: var(--accent);
}

/* ─── Feature Detail Sections ─── */
.feature-detail {
  padding: 6rem 0;
}

.feature-detail:nth-child(even) {
  background: var(--off-white);
}

.feature-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.feature-detail:nth-child(odd) .feature-detail-grid {
  direction: rtl;
}

.feature-detail:nth-child(odd) .feature-detail-grid > * {
  direction: ltr;
}

.feature-detail-content h2 {
  margin-bottom: 1rem;
}

.feature-detail-content p {
  font-size: 1.0625rem;
  line-height: 1.8;
  margin-bottom: 1.5rem;
}

.feature-detail-visual {
  background: var(--gray-100);
  border-radius: var(--radius-lg);
  padding: 2rem;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feature-detail-visual .visual-placeholder {
  text-align: center;
  color: var(--gray-400);
}

.feature-detail-visual .visual-placeholder svg {
  margin-bottom: 0.5rem;
}

/* Integrations */
.integrations-section {
  padding: 6rem 0;
}

.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  margin-top: 3rem;
}

.integration-card {
  padding: 2rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200);
  background: var(--white);
  text-align: center;
  transition: all var(--transition);
}

.integration-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--accent);
}

.integration-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-sm);
  background: var(--accent-light);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1rem;
  color: var(--accent);
}

.integration-card h3 {
  font-size: 1.125rem;
  margin-bottom: 0.5rem;
}

.integration-card p {
  font-size: 0.8125rem;
  color: var(--gray-500);
}

/* ─── Animations ─── */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 600ms ease, transform 600ms ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ─── Responsive ─── */
@media (max-width: 1024px) {
  .hero-grid {
    grid-template-columns: 1fr;
    gap: 3rem;
  }

  .hero-visual { order: -1; }

  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .steps-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-cards { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .integrations-grid { grid-template-columns: repeat(2, 1fr); }

  .feature-detail-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .feature-detail:nth-child(odd) .feature-detail-grid {
    direction: ltr;
  }
}

@media (max-width: 768px) {
  .nav-links, .header-cta { display: none; }
  .hamburger { display: flex; }
  .mobile-nav { display: flex; }

  .hero-home { padding: 7rem 0 4rem; }

  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .pricing-cards { grid-template-columns: 1fr; }
  .pricing-card.featured { transform: none; }
  .pricing-teaser-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 1.5rem; }
  .team-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr 1fr; }

  .contact-grid {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 0.75rem;
    text-align: center;
  }

  .hero-buttons {
    flex-direction: column;
  }

  .hero-buttons .btn {
    width: 100%;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .container { padding: 0 1rem; }
  .stats-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
}

